                  (wz 8) (wz needed) (wz rz) (wz size) (wz AINST) (wz SO) (Z_to_bv 64 (-8)) (wz 7) (wz TH) (wz 1) x28 x29 x30 x31)
             F (Z_to_bv 64 0x54814) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ AENV tp TSD CTX TH sb SO T rest m' /\ aframe sp ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m' j8 /\ stk bsegs m' lo (bv_unsigned sp + -128).

